import type { ArtemisPricingContent, ArtemisPricingPlan } from "../content";
const DEFAULT = {
    badge: "Choose your starting point",
    headline: "Start free. Bring us in when the stakes rise.",
    subhead: "Launch on your own today, or book a focused walkthrough when you want a rollout shaped around your team.",
    currency: "$",
    plans: [
        { name: "Starter", priceLabel: "Free", badge: "Self-serve", description: "Open a workspace, invite your team, and take the core workflow live today.", featuresTitle: "What you get", features: ["Up to 10 active projects", "One connected workspace", "Guided setup in under 10 minutes"], cta: { label: "Create workspace", href: "#" } },
        { name: "Pro", price: 650, period: "/month", badge: "Guided", description: "Bring in an expert to shape the rollout around your team and operating model.", featuresTitle: "What you get", features: ["Live working session", "A rollout mapped to your use case", "Async support after launch"], cta: { label: "Book a walkthrough", href: "#" }, featured: true },
    ],
} satisfies ArtemisPricingContent;
export default function PricingVisualPlans({ content }: { content?: Partial<ArtemisPricingContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const plans: ArtemisPricingPlan[] = copy.plans;
    const reduced = useReducedMotion();
    return (<>
      <div className="art:w-full art:self-start">
