          <div className="art:mx-auto art:w-full art:max-w-4xl">
            <motion.header className="art:mx-auto art:flex art:max-w-2xl art:flex-col art:items-center art:text-center" initial={{ opacity: 0, y: 16 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, margin: "-60px" }} transition={{ duration: 0.6, ease: ARTEMIS_EASE_OUT, y: reduced ? { duration: 0, delay: 0 } : undefined }}>
              <span className="art:flex art:size-10 art:items-center art:justify-center art:rounded-full art:bg-muted art:text-foreground">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-gem art:size-4" aria-hidden="true">
                  <path d="M10.5 3 8 9l4 13 4-13-2.5-6"/>
                  <path d="M17 3a2 2 0 0 1 1.6.8l3 4a2 2 0 0 1 .013 2.382l-7.99 10.986a2 2 0 0 1-3.247 0l-7.99-10.986A2 2 0 0 1 2.4 7.8l2.998-3.997A2 2 0 0 1 7 3z"/>
                  <path d="M2 9h20"/>
                </svg>
              </span>
              {copy.badge && <p className="art:mt-5 art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest">
                {copy.badge}
              </p>}
              <h2 className="art:mt-4 art:text-balance art:text-4xl art:font-medium art:text-foreground art:leading-tight art:tracking-tight">
                {copy.headline}
              </h2>
              {copy.subhead && <p className="art:mt-4 art:max-w-xl art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base">
                {copy.subhead}
              </p>}
            </motion.header>
            <div className="art:mt-10 art:grid art:gap-4 art:@min-[768px]/artemis:grid-cols-2">
              {plans.map((plan, index) => <motion.article key={index} whileHover={reduced ? undefined : { y: -4 }} className="art:flex art:min-h-[34rem] art:flex-col art:overflow-hidden art:rounded-3xl art:border art:border-border art:bg-transparent" initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, margin: "-60px" }} transition={{ duration: 0.6, delay: index * 0.08, ease: ARTEMIS_EASE_OUT, y: reduced ? { duration: 0, delay: 0 } : undefined }}>
                <div aria-hidden="true" className="art:h-36 art:overflow-hidden art:border-border art:border-b">
                  {index % 2 === 0 ? <div className="art:relative art:size-full art:overflow-hidden" style={{ background: "linear-gradient(125deg, #dff8f6 0%, #8ee6ee 45%, #54bde7 100%)" }}>
                    <motion.div className="art:absolute art:-top-20 art:-left-14 art:size-72 art:rounded-full art:blur-2xl" style={{ background: "radial-gradient(circle at 66% 65%, rgba(255, 255, 255, 0.94) 0%, rgba(254, 179, 156, 0.72) 26%, rgba(45, 205, 202, 0.14) 62%, transparent 74%)" }} animate={reduced ? undefined : { x: [0, 24, 0], y: [0, 10, 0], scale: [1, 1.08, 1] }} transition={{ duration: 18, ease: ARTEMIS_EASE_IN_OUT, repeat: Infinity }}/>
                    <motion.div className="art:absolute art:-right-12 art:-bottom-24 art:h-64 art:w-80 art:rounded-full art:blur-xl" style={{ background: "radial-gradient(rgba(255, 255, 255, 0.82) 0%, rgba(32, 188, 210, 0.28) 48%, transparent 72%)" }} animate={reduced ? undefined : { x: [0, -18, 0], scale: [1, 1.1, 1] }} transition={{ duration: 22, ease: ARTEMIS_EASE_IN_OUT, repeat: Infinity }}/>
                    <div className="art:absolute art:inset-0 art:opacity-45 art:[background-image:repeating-radial-gradient(ellipse_at_22%_118%,transparent_0,transparent_18px,rgba(255,255,255,0.48)_19px,transparent_20px)]"/>
                  </div> : <div className="art:relative art:size-full art:overflow-hidden" style={{ background: "linear-gradient(135deg, #a6e3ee 0%, #5ab4d2 48%, #247da8 100%)" }}>
                    <motion.div className="art:absolute art:-right-10 art:-bottom-24 art:size-72 art:rounded-full art:blur-lg" style={{ background: "radial-gradient(circle at 44% 40%, rgb(255, 247, 194) 0%, rgb(255, 186, 74) 27%, rgb(243, 107, 79) 51%, rgba(238, 69, 91, 0.22) 68%, transparent 74%)" }} animate={reduced ? undefined : { x: [0, -22, 0], y: [0, -8, 0], scale: [1, 1.06, 1] }} transition={{ duration: 20, ease: ARTEMIS_EASE_IN_OUT, repeat: Infinity }}/>
                    <motion.div className="art:absolute art:-bottom-20 art:-left-20 art:h-44 art:w-80 art:rounded-full art:blur-2xl" style={{ background: "radial-gradient(rgba(255, 188, 94, 0.82) 0%, rgba(245, 100, 91, 0.34) 48%, transparent 72%)" }} animate={reduced ? undefined : { x: [0, 28, 0], scale: [1, 1.12, 1] }} transition={{ duration: 24, ease: ARTEMIS_EASE_IN_OUT, repeat: Infinity }}/>
                    <div className="art:absolute art:inset-0 art:opacity-20 art:[background-image:repeating-linear-gradient(90deg,rgba(255,255,255,0.55)_0,rgba(255,255,255,0.55)_1px,transparent_1px,transparent_3px)]"/>
                  </div>}
                </div>
                <div className="art:flex art:flex-1 art:flex-col art:p-6 art:@min-[640px]/artemis:p-7">
                  <div className="art:flex art:items-start art:justify-between art:gap-4">
                    <div>
                      <h3 className="art:text-xl art:font-medium art:text-foreground">
                        {plan.name}
