                      <div className="art:mt-2 art:flex art:items-baseline art:gap-1.5">
                        <span className="art:font-sans art:font-medium art:text-foreground art:text-2xl art:tracking-tight">
                          {plan.priceLabel ?? `${copy.currency}${plan.price ?? 0}`}
                        </span>
                        {plan.priceLabel === undefined && plan.period && <span className="art:text-muted-foreground art:text-sm">
                          {plan.period}
                        </span>}
                      </div>
                    </div>
                    {plan.badge && <span className="art:shrink-0 art:whitespace-nowrap art:rounded-full art:bg-gradient-to-r art:from-primary/10 art:via-muted art:to-background art:px-2.5 art:py-1 art:font-medium art:text-muted-foreground art:text-xs">
                      {plan.badge}
                    </span>}
                  </div>
                  {plan.description && <p className="art:mt-5 art:max-w-md art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">
                    {plan.description}
                  </p>}
                  <div className="art:mt-7 art:border-border art:border-t art:pt-6">
                    {plan.featuresTitle && <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest">
                      {plan.featuresTitle}
                    </p>}
                    <ul className="art:mt-4 art:space-y-3.5">
                      {plan.features.map((feature, item) => <li key={item} className="art:flex art:items-start art:gap-3 art:text-foreground/75 art:text-sm art:leading-5">
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-circle-check art:mt-0.5 art:size-4 art:shrink-0 art:text-foreground" aria-hidden="true">
                          <circle cx="12" cy="12" r="10"/>
                          <path d="m9 12 2 2 4-4"/>
                        </svg>
                        <span>
                          {feature}
                        </span>
                      </li>)}
                    </ul>
                  </div>
                  <div className="art:mt-auto art:pt-8">
                    <motion.a whileHover={reduced ? undefined : { scale: 1.01 }} whileTap={reduced ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS} className={plan.featured ? "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-6 art:text-base art:w-full art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full" : "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:px-6 art:text-base art:w-full art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full"} href={plan.cta.href.split("{billing}").join("monthly")} tabIndex={0}>
                      {plan.cta.label}
                    </motion.a>
                  </div>
                </div>
              </motion.article>)}
            </div>
          </div>
        </section>
      </div>
    </>);
}
